import { test, expect } from '@playwright/test';

test.describe('Password Strength Indicator', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000/set-password');
  });

  test('should display password strength indicator when user enters a weak password', async ({ page }) => {
    const passwordInput = page.getByLabel('New Password');
    await passwordInput.fill('123');

    const strengthIndicator = page.getByRole('status', { name: /password strength/i });
    await expect(strengthIndicator).toBeVisible();

    const weakIndicator = page.getByText('Weak', { exact: true });
    await expect(weakIndicator).toBeVisible();
  });

  test('should display password strength indicator when user enters a strong password', async ({ page }) => {
    const passwordInput = page.getByLabel('New Password');
    await passwordInput.fill('SecureP@ssw0rd123!');

    const strengthIndicator = page.getByRole('status', { name: /password strength/i });
    await expect(strengthIndicator).toBeVisible();

    const strongIndicator = page.getByText('Strong', { exact: true });
    await expect(strongIndicator).toBeVisible();
  });

  test('should update password strength indicator as user types', async ({ page }) => {
    const passwordInput = page.getByLabel('New Password');

    await passwordInput.fill('pass');
    let weakIndicator = page.getByText('Weak', { exact: true });
    await expect(weakIndicator).toBeVisible();

    await passwordInput.fill('password123');
    let mediumIndicator = page.getByText('Medium', { exact: true });
    await expect(mediumIndicator).toBeVisible();

    await passwordInput.fill('SecureP@ssw0rd123!');
    let strongIndicator = page.getByText('Strong', { exact: true });
    await expect(strongIndicator).toBeVisible();
  });

  test('should hide password strength indicator when password field is empty', async ({ page }) => {
    const passwordInput = page.getByLabel('New Password');
    await passwordInput.fill('TestPassword123');

    let strengthIndicator = page.getByRole('status', { name: /password strength/i });
    await expect(strengthIndicator).toBeVisible();

    await passwordInput.clear();
    await expect(strengthIndicator).not.toBeVisible();
  });

  test('should display visual feedback with color coding for password strength', async ({ page }) => {
    const passwordInput = page.getByLabel('New Password');
    await passwordInput.fill('weak');

    const strengthBar = page.getByRole('progressbar', { name: /strength/i });
    await expect(strengthBar).toBeVisible();

    const weakColor = await strengthBar.evaluate((el) => {
      return window.getComputedStyle(el).backgroundColor;
    });
    expect(weakColor).toBeTruthy();

    await passwordInput.fill('VeryStr0ng!P@ssw0rd');
    const strongColor = await strengthBar.evaluate((el) => {
      return window.getComputedStyle(el).backgroundColor;
    });
    expect(strongColor).toBeTruthy();
    expect(weakColor).not.toBe(strongColor);
  });
});
